import java.io.IOException;
import java.nio.channels.Channels;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.SecureDirectoryStream;
import java.nio.file.StandardOpenOption;
import java.util.Properties;
import java.util.Set;

public class ProcDirectoryProbe {
    public static void main(String[] args) throws IOException, InterruptedException {
        if (args[0].equals("child")) {
            System.out.println("READY");
            System.out.flush();
            System.in.read();
            return;
        }

        Path classes = Path.of(args[0]);
        Path procRoot = Path.of(args[1]);
        Path java = Path.of(System.getProperty("java.home")).resolve("bin/java");
        Process child = new ProcessBuilder(java.toString(), "-cp", classes.toString(),
            "ProcDirectoryProbe", "child").redirectError(ProcessBuilder.Redirect.INHERIT).start();
        try {
            try (var output = child.inputReader(StandardCharsets.UTF_8)) {
                if ("READY".equals(output.readLine()) == false)
                    throw new IOException("Child did not report READY");

                Path processDirectory = procRoot.resolve(Long.toString(child.pid()));
                try (var directory = Files.newDirectoryStream(processDirectory)) {
                    System.out.println("provider=" + directory.getClass().getName());
                    if (directory instanceof SecureDirectoryStream<Path> secure) {
                        System.out.println("pid=" + child.pid());
                        System.out.println("startInstant=" + child.info().startInstant());
                        try (var status = secure.newByteChannel(Path.of("status"), Set.of(StandardOpenOption.READ));
                             var reader = Channels.newReader(status, StandardCharsets.UTF_8)) {
                            Properties counters = new Properties();
                            counters.load(reader);
                            System.out.println("live.VmRSS=" + counters.getProperty("VmRSS"));
                            System.out.println("live.Pid=" + counters.getProperty("Pid"));
                        }

                        try (var missing = secure.newByteChannel(Path.of("missing-counter-file"),
                            Set.of(StandardOpenOption.READ))) {
                            throw new AssertionError("Missing file unexpectedly opened");
                        } catch (java.nio.file.NoSuchFileException expected) {
                            System.out.println("missing=" + expected.getClass().getName());
                        }

                        child.getOutputStream().close();
                        System.out.println("child.exit=" + child.waitFor());
                        System.out.println("path.exists.after=" + Files.exists(processDirectory));
                        try (var stale = secure.newByteChannel(Path.of("status"), Set.of(StandardOpenOption.READ))) {
                            throw new AssertionError("Exited process status unexpectedly opened");
                        } catch (IOException expected) {
                            System.out.println("stale=" + expected.getClass().getName() + ": " + expected.getMessage());
                        }
                    } else {
                        throw new UnsupportedOperationException("Provider exposes no secure directory stream");
                    }
                }
            }
        } finally {
            child.destroyForcibly();
            child.waitFor();
        }
    }
}
